// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { FacetValueLabels } from "../../../main/frontend/graph-explorer/facet-value-labels.ts";
import { memoryFacetBackend } from "../../../main/frontend/graph-explorer/facet-store-persistence.ts";
import { valueLabelQuery, RDFS_LABEL } from "../../../main/frontend/graph-explorer/rdf-vocabulary.ts";

const EX = "http://example.org/";
const SKOS = "http://www.w3.org/2004/02/skos/core#prefLabel";

/** Answers value label queries from `labels`: iri → [label, language, property][]. */
function fakeLabels(labels, { saturateAbove = Infinity } = {}) {
  const queries = [];
  const execute = async (query) => {
    queries.push(query);
    const ids = [...new Set([...(query.match(/VALUES \?resource \{([^}]*)\}/)?.[1] ?? "").matchAll(/<([^>]+)>/g)].map((m) => m[1]))];
    const bindings = ids.flatMap((id) => (labels[id] ?? []).map(([value, language, property]) => ({
      resource: { type: "uri", value: id },
      labelProperty: { type: "uri", value: property ?? RDFS_LABEL },
      label: { type: "literal", value, ...(language ? { "xml:lang": language } : {}) },
    })));
    if (ids.length > saturateAbove) return { results: { bindings: new Array(4096).fill(bindings[0]) } };
    return { results: { bindings } };
  };
  return { execute, queries };
}

async function settled(labels) {
  for (let turn = 0; turn < 2000; turn++) {
    if (!labels.pending()) return;
    await new Promise((resolve) => setTimeout(resolve, 1));
  }
  throw new Error("labels did not settle");
}

const askedFor = (query) => [...(query.match(/VALUES \?resource \{([^}]*)\}/)?.[1] ?? "").matchAll(/<([^>]+)>/g)].map((m) => m[1]);

test("the value label query restricts each branch to the values and leaves the scope's statements alone", () => {
  const query = valueLabelQuery([`${EX}acme`], [SKOS], "all");
  assert.equal(query.match(/VALUES \?resource \{ <http:\/\/example\.org\/acme> \}/g)?.length, 4,
    "direct and SKOS-XL branches, each in the default graph and in named graphs");
  assert.match(query, /LIMIT 4096$/);
});

test("each value IRI is asked for once and gets its best label for the preferred languages", async () => {
  const repository = fakeLabels({
    [`${EX}acme`]: [["Acme", "en"], ["Akme", "nb"]],
    [`${EX}oslo`]: [["Oslo", ""]],
  });
  const labels = new FacetValueLabels({ execute: repository.execute, scope: "default", namespace: "n", languages: ["nb", "en"] });
  labels.want([`${EX}acme`, `${EX}oslo`, `${EX}nolabel`], "background");
  await settled(labels);
  assert.equal(labels.label(`${EX}acme`), "Akme");
  assert.equal(labels.label(`${EX}oslo`), "Oslo");
  assert.equal(labels.label(`${EX}nolabel`), undefined);
  labels.want([`${EX}acme`, `${EX}nolabel`], "shown");
  await settled(labels);
  assert.equal(repository.queries.length, 1, "known labels and known absences are not asked for again");
});

test("labels the canvas already knows cost no query", async () => {
  const repository = fakeLabels({});
  const labels = new FacetValueLabels({
    execute: repository.execute, scope: "default", namespace: "n", languages: ["en"],
    known: (iri) => (iri === `${EX}bob` ? "Bob" : undefined),
  });
  labels.want([`${EX}bob`], "shown");
  await settled(labels);
  assert.equal(labels.label(`${EX}bob`), "Bob");
  assert.equal(repository.queries.length, 0);
});

test("stored labels are used without asking, and new ones are stored", async () => {
  const backend = memoryFacetBackend();
  const first = new FacetValueLabels({ execute: fakeLabels({ [`${EX}acme`]: [["Acme", "en"]] }).execute,
    scope: "default", namespace: "n", languages: ["en"], backend });
  first.want([`${EX}acme`], "shown");
  await settled(first);
  const repository = fakeLabels({});
  const second = new FacetValueLabels({ execute: repository.execute, scope: "default", namespace: "n", languages: ["en"], backend });
  second.want([`${EX}acme`], "shown");
  await settled(second);
  assert.equal(second.label(`${EX}acme`), "Acme");
  assert.equal(repository.queries.length, 0);
});

test("values the panel shows are labelled before the rest", async () => {
  const repository = fakeLabels({});
  const labels = new FacetValueLabels({ execute: repository.execute, scope: "default", namespace: "n", languages: ["en"], batchSize: 1 });
  labels.want([`${EX}a`, `${EX}b`], "background");
  labels.want([`${EX}shown`], "shown");
  await settled(labels);
  assert.deepEqual(askedFor(repository.queries[0]), [`${EX}shown`]);
});

test("a reply at the label query's row limit is asked for again in halves", async () => {
  const data = {};
  for (let index = 0; index < 8; index++) data[`${EX}v${index}`] = [[`V${index}`, "en"]];
  const repository = fakeLabels(data, { saturateAbove: 2 });
  const labels = new FacetValueLabels({ execute: repository.execute, scope: "default", namespace: "n", languages: ["en"] });
  labels.want(Object.keys(data), "background");
  await settled(labels);
  assert.deepEqual(Object.keys(data).map((iri) => labels.label(iri)), Object.keys(data).map((_, index) => `V${index}`));
});
